import numpy as np
from scipy.optimize import root, least_squares

def D_ab(a, b):
    # KL Bern(a)||Bern(b), a,b in (0,1)
    a = np.clip(a, 1e-15, 1-1e-15)
    b = np.clip(b, 1e-15, 1-1e-15)
    return a*np.log(a/b) + (1-a)*np.log((1-a)/(1-b))

def F(x):
    t, al = x
    return np.array([D_ab(al,t)-10.0, D_ab(t,al)-10.0])

# Try several starts. Need t < al.
starts = [(0.5,0.9),(0.1,0.5),(0.01,0.1),(0.001,0.01),(0.001,0.1),(0.01,0.3),(0.3,0.99)]
for s in starts:
    try:
        sol = root(F, s)
        if sol.success:
            t, al = sol.x
            if 0<t<al<1:
                print("start", s, "-> t=%.10f al=%.10f"%(t,al), "err", F(sol.x))
        else:
            # least_squares fallback
            ls = least_squares(F, s, bounds=([1e-12,1e-12],[1-1e-12,1-1e-12]))
            if np.max(np.abs(ls.fun)) < 1e-6:
                t, al = ls.x
                if 0<t<al<1:
                    print("ls start", s, "-> t=%.10f al=%.10f"%(t,al), "err", ls.fun)
    except Exception as e:
        print(s, "err", e)
